{
  "findings": [
    {
      "check_id": "CKV_AZURE_221",
      "title": "Ensure that Azure Function App public network access is disabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The resource does not explicitly disable public network access, defaulting to allowing traffic from any IP address. This increases the attack surface for the function app."
    },
    {
      "check_id": "CKV_AZURE_70",
      "title": "Ensure that Function apps is only accessible over HTTPS",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The site_config block does not enforce HTTPS-only traffic (https_only = true), potentially allowing insecure HTTP requests to reach the application."
    }
  ],
  "patched_code": "resource \"azurerm_linux_function_app\" \"alert_function\" {\n  name                = \"smart-manufacturing-iot-monitoring-platform-function-app-alerts\"\n  resource_group_name = azurerm_resource_group.smart_manufacturing.name\n  location            = azurerm_resource_group.smart_manufacturing.location\n  service_plan_id     = azurerm_service_plan.dashboard_plan.id\n  storage_account_name       = azurerm_storage_account.function_storage.name\n  storage_account_access_key = azurerm_storage_account.function_storage.primary_access_key\n  https_only          = true\n  site_config {\n    application_stack {\n      node_version = \"18\"\n    }\n    ip_restriction {\n      ip_address = \"0.0.0.0/32\"\n    }\n  }\n  app_settings = {\n    \"FUNCTIONS_WORKER_RUNTIME\" = \"node\"\n  }\n}",
  "fix_summary": "Added 'https_only = true' to enforce HTTPS traffic and added an 'ip_restriction' block with a deny-all rule (0.0.0.0/32) within 'site_config' to effectively disable public network access, requiring explicit allow-list rules for connectivity."
}
